      this.proto(head, "cow_head", white, [0, 0, 0], [0.6, 0.52, 0.5]);
      this.sphere(head, patches, [-0.3, 0.34, 0.3], [0.25, 0.18, 0.12], [0, 0, -0.2], 20);
      this.sphere(head, patches, [0.35, 0.3, 0.3], [0.19, 0.14, 0.11], [0, 0, 0.22], 20);
